#!/usr/bin/env python3
"""Stream Premier Draft game logs and compute per-card GIH / deck / OH win rates."""
import csv, gzip, json, sys, time
from pathlib import Path

SETS = ["HOB", "MSH", "SOS", "TMT", "ECL", "TLA", "OM1", "EOE", "FIN", "TDM"]
ROOT = Path("/opt/mtg-data/17lands/sets")
OUT = Path("/tmp/fra/gih")
OUT.mkdir(parents=True, exist_ok=True)

def compute(set_code: str):
    path = ROOT / set_code / f"game_data_public.{set_code}.PremierDraft.csv.gz"
    if not path.exists():
        # pick two only sets
        alt = list((ROOT / set_code).glob("game_data_public.*.PremierDraft.csv.gz"))
        if not alt:
            print("MISSING", set_code, flush=True)
            return
        path = alt[0]
    t0 = time.time()
    gih_n = {}
    gih_w = {}
    deck_n = {}
    deck_w = {}
    oh_n = {}
    oh_w = {}
    drawn_n = {}
    drawn_w = {}
    games = 0
    wins = 0
    # color stats
    color_n = {}
    color_w = {}
    with gzip.open(path, "rt", newline="") as handle:
        reader = csv.reader(handle)
        header = next(reader)
        index = {name: i for i, name in enumerate(header)}
        won_i = index["won"]
        colors_i = index.get("main_colors")
        # card -> (oh, drawn, deck) indices; -1 if missing
        cards = []
        names = []
        for name, i in index.items():
            if name.startswith("opening_hand_"):
                card = name[len("opening_hand_"):]
                names.append(card)
        name_set = set(names)
        for card in names:
            oh = index.get(f"opening_hand_{card}", -1)
            dr = index.get(f"drawn_{card}", -1)
            dk = index.get(f"deck_{card}", -1)
            cards.append((card, oh, dr, dk))
            gih_n[card] = 0
            gih_w[card] = 0
            deck_n[card] = 0
            deck_w[card] = 0
            oh_n[card] = 0
            oh_w[card] = 0
            drawn_n[card] = 0
            drawn_w[card] = 0
        for row in reader:
            games += 1
            won_raw = row[won_i]
            won = won_raw in {"1", "True", "true", "TRUE"}
            if won:
                wins += 1
            if colors_i is not None:
                col = row[colors_i] or "none"
                color_n[col] = color_n.get(col, 0) + 1
                if won:
                    color_w[col] = color_w.get(col, 0) + 1
            for card, oh, dr, dk in cards:
                in_deck = False
                if dk >= 0:
                    v = row[dk]
                    if v and v != "0":
                        in_deck = True
                        deck_n[card] += 1
                        if won:
                            deck_w[card] += 1
                in_oh = False
                in_dr = False
                if oh >= 0:
                    v = row[oh]
                    if v and v != "0":
                        in_oh = True
                if dr >= 0:
                    v = row[dr]
                    if v and v != "0":
                        in_dr = True
                if in_oh or in_dr:
                    gih_n[card] += 1
                    if won:
                        gih_w[card] += 1
                if in_oh:
                    oh_n[card] += 1
                    if won:
                        oh_w[card] += 1
                if in_dr:
                    drawn_n[card] += 1
                    if won:
                        drawn_w[card] += 1
    rows = []
    for card in names:
        gn = gih_n[card]
        dn = deck_n[card]
        rows.append({
            "set": set_code,
            "card": card,
            "gih_n": gn,
            "gih_wins": gih_w[card],
            "gih_wr": (gih_w[card] / gn) if gn else None,
            "deck_n": dn,
            "deck_wins": deck_w[card],
            "deck_wr": (deck_w[card] / dn) if dn else None,
            "oh_n": oh_n[card],
            "oh_wr": (oh_w[card] / oh_n[card]) if oh_n[card] else None,
            "drawn_n": drawn_n[card],
            "drawn_wr": (drawn_w[card] / drawn_n[card]) if drawn_n[card] else None,
        })
    out = OUT / f"{set_code}.json"
    payload = {
        "set": set_code,
        "games": games,
        "wins": wins,
        "game_wr": wins / games if games else None,
        "n_cards": len(names),
        "colors": [
            {"colors": c, "n": color_n[c], "wr": color_w.get(c, 0) / color_n[c]}
            for c in sorted(color_n, key=lambda k: -color_n[k])
        ],
        "cards": rows,
    }
    out.write_text(json.dumps(payload))
    elapsed = time.time() - t0
    print(f"{set_code} games={games} wr={wins/games:.4f} cards={len(names)} sec={elapsed:.1f}", flush=True)

if __name__ == "__main__":
    only = sys.argv[1:] or SETS
    for s in only:
        compute(s)
END
